std::string context;
void check(bool ok,const std::string& why){if(!ok)throw std::runtime_error(context+": "+why);}
std::vector<Pixel> words(const JsonArray& a){std::vector<Pixel> result;for(auto v:a)result.push_back(Pixel(v.GetNumber()));return result;}
void pixels(const std::vector<Pixel>& actual,const JsonArray& expected){check(actual==words(expected),"raw IDs");}
std::vector<CurvePoint> curve(const JsonArray& a){std::vector<CurvePoint> out;for(auto v:a){auto p=v.GetObject();out.push_back({p.GetNamedNumber(L"x"),p.GetNamedNumber(L"y")});}return out;}
ColorAdjustment spec(const JsonObject& row){auto s=row.GetNamedObject(L"spec");auto k=s.GetNamedString(L"kind");ColorAdjustment a;
 if(k==L"brightness-contrast"){a.brightness=s.GetNamedNumber(L"brightness",0);a.contrast=s.GetNamedNumber(L"contrast",0);}
 else if(k==L"hue-saturation"){a.kind=ColorAdjustmentKind::HueSaturation;a.hue=s.GetNamedNumber(L"hue",0);a.saturation=s.GetNamedNumber(L"saturation",0);a.lightness=s.GetNamedNumber(L"lightness",0);a.colorize=s.GetNamedBoolean(L"colorize",false);}
 else if(k==L"color-balance"){a.kind=ColorAdjustmentKind::ColorBalance;a.balance[0]={35,-17,0};a.balance[1]={0,0,28};a.balance[2]={-23,0,0};a.preserveLuminosity=s.GetNamedBoolean(L"preserveLuminosity");}
 else if(k==L"curves"){a.kind=s.GetNamedBoolean(L"invert",false)?ColorAdjustmentKind::Invert:ColorAdjustmentKind::Curves;a.curves[0]=curve(s.GetNamedArray(L"curvePoints"));a.curves[1]=curve(s.GetNamedArray(L"curveRedPoints"));}
 else {a.kind=ColorAdjustmentKind::GradientMap;auto g=s.GetNamedObject(L"gradientMap");a.gradientMap.steps=g.GetNamedString(L"mode")==L"steps";a.gradientMap.reverse=g.GetNamedBoolean(L"reverse");a.gradientMap.dither=int(row.GetNamedNumber(L"dither"));a.gradientMap.stops.clear();for(auto v:g.GetNamedArray(L"stops")){auto stop=v.GetObject();auto c=stop.GetNamedObject(L"color");a.gradientMap.stops.push_back({stop.GetNamedNumber(L"position"),Pixel(c.GetNamedNumber(L"r"))|(Pixel(c.GetNamedNumber(L"g"))<<8)|(Pixel(c.GetNamedNumber(L"b"))<<16)|0xff000000});}}
 return a;
}
void palette(const PaletteState& p,const JsonObject& expected){const auto e=expected.GetNamedArray(L"entries");check(p.entries.size()==e.Size(),"palette count");for(unsigned i=0;i<e.Size();++i){auto v=e.GetObjectAt(i);check(p.entries[i].id==int(v.GetNamedNumber(L"id"))&&p.entries[i].color==Pixel(v.GetNamedNumber(L"color")),"palette entry "+std::to_string(i));const auto n=winrt::to_string(v.GetNamedString(L"name"));check(p.entries[i].name==std::u32string(n.begin(),n.end()),"palette name");}const auto order=words(expected.GetNamedArray(L"order"));auto actual=p.order();check(std::vector<Pixel>(actual.begin(),actual.end())==order&&p.nextId==int(expected.GetNamedNumber(L"nextId")),"palette order/allocator");}
void encoded(const Document& d){bool duplicates=false;std::unordered_set<int> ids;for(const auto& e:d.palette().entries)duplicates|=!ids.insert(e.id).second;
 for(int k=0;k<3;++k){try{auto out=k==0?project::encodeEditableProject(d):k==1?project::encodeRecoveryProject(d):project::encodeHistoryProject(d);check(!duplicates,"encoder accepted duplicates");auto m=project::readProjectManifest(out.bytes);project::Archive zip(out.bytes);check(m.colorMode=="indexed","encoded mode");for(const auto& c:m.cels)if(c.surface){const auto* runtime=d.timeline().resolveSurface(c.id).surface;const auto& s=*c.surface;check(runtime&&s.format==project::RasterFormat::Indexed&&project::decodeRaster(zip.read(s.dataFile,project::Limits{}.expandedBytes),s.dataEncoding,s.format,s.width,s.height,project::Limits{}.expandedBytes)==runtime->pixels,"encoded raw IDs");}check(m.palette.size()==d.palette().entries.size(),"encoded palette");bool gated=false;try{project::prepareEditableImport(m);}catch(const project::Error& e){gated=e.kind==project::ErrorKind::Unsupported;}check(gated,"production indexed gate");}catch(const project::Error& e){check(duplicates&&e.kind==project::ErrorKind::Corrupt,"encoder error");}}
}
