  d->timeline_=timeline::Timeline(std::move(state));d->colorMode_=color_mode::Mode::Indexed;auto& p=d->palette_;p.entries.clear();for(auto v:row.GetNamedArray(L"entries")){auto e=v.GetObject();auto name=winrt::to_string(e.GetNamedString(L"name"));p.entries.push_back({int(e.GetNamedNumber(L"id")),std::u32string(name.begin(),name.end()),Pixel(e.GetNamedNumber(L"color"))});}std::vector<int> order;for(auto id:words(row.GetNamedArray(L"order")))order.push_back(int(id));p.setOrder(order);p.nextId=100;
  if(row.GetNamedValue(L"selection").ValueType()==JsonValueType::Object){auto v=row.GetNamedObject(L"selection");SelectionMask s{int(v.GetNamedNumber(L"x")),int(v.GetNamedNumber(L"y")),int(v.GetNamedNumber(L"width")),int(v.GetNamedNumber(L"height")),{}};for(auto b:words(v.GetNamedArray(L"mask")))s.mask.push_back(std::uint8_t(b));d->previewSelection(s);}d->projectActiveCelOpacities();d->markSaved();return d;
